{
  "category_edits": [
    {
      "category": "network_architecture",
      "rationale": "Append one same-width GRU layer with a residual connection before the existing readout and scoring. The residual path preserves the original representation while the additional recurrent layer can learn higher-order patterns. Store its depth and update the predictor writer to reconstruct the same single-model architecture. Preserve embeddings, histories, loss, optimizer, routing, seeds and epoch settings.",
      "edits": [
        {
          "find": "                 dropout_rate: float = 0.1):\n        super().__init__()",
          "replace": "                 dropout_rate: float = 0.1, residual_layers: int = 1):\n        super().__init__()"
        },
        {
          "find": "        self.gru = nn.GRU(hidden_units, hidden_units, num_layers=num_layers,\n                          batch_first=True, dropout=dropout)\n        self.dropout = nn.Dropout(dropout_rate)",
          "replace": "        self.gru = nn.GRU(hidden_units, hidden_units, num_layers=num_layers,\n                          batch_first=True, dropout=dropout)\n        self.residual_gru = nn.GRU(\n            hidden_units, hidden_units, num_layers=residual_layers,\n            batch_first=True,\n        )\n        self.dropout = nn.Dropout(dropout_rate)"
        },
        {
          "find": "        out, _ = self.gru(emb)\n        # Histories are LEFT padded; count-1 indexes padding on short histories.",
          "replace": "        out, _ = self.gru(emb)\n        residual, _ = self.residual_gru(out)\n        out = out + residual\n        # Histories are LEFT padded; count-1 indexes padding on short histories."
        },
        {
          "find": "        out, _ = self.gru(emb)\n        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)",
          "replace": "        out, _ = self.gru(emb)\n        residual, _ = self.residual_gru(out)\n        out = out + residual\n        pos_scores = (out * self.item_emb(pos)).sum(dim=-1)"
        },
        {
          "find": "            \"num_layers\": NUM_LAYERS,\n            \"dropout_rate\": DROPOUT_RATE,",
          "replace": "            \"num_layers\": NUM_LAYERS,\n            \"residual_layers\": model.residual_gru.num_layers,\n            \"dropout_rate\": DROPOUT_RATE,"
        },
        {
          "find": "            num_layers=meta[\"num_layers\"],\n            dropout_rate=0.0,",
          "replace": "            num_layers=meta[\"num_layers\"],\n            residual_layers=meta[\"residual_layers\"],\n            dropout_rate=0.0,"
        }
      ]
    }
  ],
  "change_summary": "Add one jointly trained residual GRU layer to each category model and synchronize checkpoint metadata with the generated predictor."
}
